// src/revenue/types.ts
export interface RevenueInput {
  quantity: number;
  unitPriceMinor: number;
  discountMinor?: number;
}

export interface RevenueResult {
  subtotalMinor: number;
  discountMinor: number;
  totalMinor: number;
}

// src/revenue/calculateRevenue.ts
import { RevenueInput, RevenueResult } from './types';

export function calculateRevenue(input: RevenueInput): RevenueResult {
  const { quantity, unitPriceMinor, discountMinor = 0 } = input;

  if (!Number.isInteger(quantity) || quantity < 0) {
    throw new Error('quantity must be a non-negative integer');
  }
  if (!Number.isInteger(unitPriceMinor) || unitPriceMinor < 0) {
    throw new Error('unitPriceMinor must be a non-negative integer');
  }
  if (!Number.isInteger(discountMinor) || discountMinor < 0) {
    throw new Error('discountMinor must be a non-negative integer');
  }

  const subtotalMinor = quantity * unitPriceMinor;

  if (discountMinor > subtotalMinor) {
    throw new Error('discountMinor cannot exceed subtotal');
  }

  return {
    subtotalMinor,
    discountMinor,
    totalMinor: subtotalMinor - discountMinor,
  };
}

// src/api/contracts.ts
import { RevenueInput, RevenueResult } from '../revenue/types';
export type CalculateRevenueRequest = RevenueInput;
export type CalculateRevenueResponse = RevenueResult;

// test/revenue/calculateRevenue.test.ts
import { calculateRevenue } from '../../src/revenue/calculateRevenue';

describe('calculateRevenue', () => {
  it('calculates standard revenue case', () => {
    expect(calculateRevenue({ quantity: 5, unitPriceMinor: 1000, discountMinor: 500 }))
      .toEqual({ subtotalMinor: 5000, discountMinor: 500, totalMinor: 4500 });
  });

  it('handles zero quantity', () => {
    expect(calculateRevenue({ quantity: 0, unitPriceMinor: 1000, discountMinor: 0 }))
      .toEqual({ subtotalMinor: 0, discountMinor: 0, totalMinor: 0 });
  });

  it('handles zero discount', () => {
    expect(calculateRevenue({ quantity: 3, unitPriceMinor: 250, discountMinor: 0 }))
      .toEqual({ subtotalMinor: 750, discountMinor: 0, totalMinor: 750 });
  });

  it('allows discount equal to subtotal', () => {
    expect(calculateRevenue({ quantity: 2, unitPriceMinor: 400, discountMinor: 800 }))
      .toEqual({ subtotalMinor: 800, discountMinor: 800, totalMinor: 0 });
  });

  it('rejects negative quantity', () => {
    expect(() => calculateRevenue({ quantity: -1, unitPriceMinor: 100, discountMinor: 0 }))
      .toThrow('quantity must be a non-negative integer');
  });

  it('rejects discount greater than subtotal', () => {
    expect(() => calculateRevenue({ quantity: 1, unitPriceMinor: 100, discountMinor: 101 }))
      .toThrow('discountMinor cannot exceed subtotal');
  });
});

